//! Complete backup: the portable domain archive plus a manifest of the
//! non-rebuildable content on disk. Rebuildable caches are named and excluded
//! instead of being copied into the archive.
use super::super::{digest, durable::{fields, text}, worlds, TaskJournal};
use anyhow::{ensure, Context, Result};
use rusqlite::{params, OptionalExtension, TransactionBehavior};
use serde_json::{json, Value};
use sha2::{Digest as _, Sha256};
use std::path::{Path, PathBuf};

pub(super) const FORMAT: &str = "craftmine.complete-backup/1";
pub(super) const SCHEMA_VERSION: u64 = 1;

#[cfg(test)]
#[path = "complete_tests.rs"]
mod tests;

/// Caches that a restore may rebuild from source. They are listed so an
/// operator can see what was deliberately left out.
const REBUILDABLE: &[(&str, &str)] = &[
    (
        "godot-import-cache",
        "regenerated by the Godot importer from the backed-up source",
    ),
    (
        "godot-build-artifacts",
        "rebuilt by the managed build job from the backed-up source",
    ),
    (
        "godot-export-artifacts",
        "rebuilt from an applied build instead of being shipped",
    ),
];

fn archive_root(directory: &Path, id: &str) -> Result<PathBuf> {
    worlds::validate_id(id)?;
    Ok(directory.join("legacy-imports").join(id))
}

fn ordinary(path: &Path) -> bool {
    std::fs::symlink_metadata(path)
        .is_ok_and(|meta| meta.is_file() && !meta.file_type().is_symlink())
}

fn relative(name: &str) -> bool {
    !name.is_empty()
        && name.len() <= 240
        && !name.contains(['\\', ':'])
        && name
            .split('/')
            .all(|part| !part.is_empty() && part != "." && part != "..")
}

fn bytes_hash(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// Manifest of the sealed legacy archives, which are the only non-rebuildable
/// bytes that do not already live inside the domain tables.
fn content_manifest(db: &rusqlite::Connection) -> Result<Value> {
    let mut statement = db
        .prepare("SELECT id,manifest,manifest_hash,world_id FROM craftmine_legacy_imports ORDER BY id")?;
    let rows = statement
        .query_map([], |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, String>(1)?,
                r.get::<_, String>(2)?,
                r.get::<_, Option<String>>(3)?,
            ))
        })?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    let mut imports = Vec::new();
    for (id, manifest, manifest_hash, world_id) in rows {
        ensure!(
            digest(&manifest) == manifest_hash,
            "CORRUPT_IMPORT_MANIFEST: {}",
            id
        );
        let value: Value = serde_json::from_str(&manifest)?;
        let mut files = Vec::new();
        if let Some(map) = value["files"].as_object() {
            for (path, record) in map {
                ensure!(relative(path), "INVALID_ARCHIVE_PATH: {}", path);
                files.push(json!({"path": path, "bytes": record["bytes"], "hash": record["hash"]}));
            }
        }
        files.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
        imports.push(json!({"id": id, "manifestHash": manifest_hash, "files": files,
            "bytes": value["bytes"], "worldId": world_id}));
    }
    Ok(json!({"legacyImports": imports}))
}

fn rebuildable() -> Value {
    json!(REBUILDABLE
        .iter()
        .map(|(kind, reason)| json!({"kind": kind, "reason": reason, "excluded": true}))
        .collect::<Vec<_>>())
}

fn body(created_at: i64, domain: &Value, content: &Value) -> Value {
    json!({
        "format": FORMAT,
        "schemaVersion": SCHEMA_VERSION,
        "createdAt": created_at,
        "domain": domain,
        "content": content,
        "rebuildable": rebuildable(),
        "provenance": {"domainHash": domain["hash"], "credentialsIncluded": false}
    })
}

fn content_report(db: &rusqlite::Connection, directory: &Path, content: &Value) -> Result<Value> {
    let mut missing = Vec::new();
    let mut mismatched = Vec::new();
    let mut path_escapes = Vec::new();
    let mut verified = 0u64;
    let imports = content["legacyImports"]
        .as_array()
        .context("BACKUP_CONTENT_REQUIRED")?;
    for import in imports {
        let id = import["id"].as_str().context("BACKUP_IMPORT_ID_REQUIRED")?;
        let root = archive_root(directory, id)?;
        let manifest_path = root.join("manifest.json");
        if !ordinary(&manifest_path) {
            missing.push(json!({"path": format!("legacy-imports/{id}/manifest.json"),
                "reason": "missing"}));
            continue;
        }
        if bytes_hash(&std::fs::read(&manifest_path)?) != import["manifestHash"] {
            mismatched.push(json!({"path": format!("legacy-imports/{id}/manifest.json"),
                "reason": "manifest hash mismatch"}));
        }
        for file in import["files"].as_array().context("BACKUP_FILES_REQUIRED")? {
            let name = file["path"].as_str().context("BACKUP_PATH_REQUIRED")?;
            if !relative(name) {
                path_escapes.push(json!({"path": name, "reason": "unsafe relative path"}));
                continue;
            }
            let path = root.join("source").join(name);
            let shown = format!("legacy-imports/{id}/source/{name}");
            if !ordinary(&path) {
                missing.push(json!({"path": shown, "reason": "missing"}));
                continue;
            }
            let bytes = std::fs::read(&path)?;
            if file["bytes"].as_u64() != Some(bytes.len() as u64)
                || file["hash"].as_str() != Some(bytes_hash(&bytes).as_str())
            {
                mismatched.push(json!({"path": shown, "reason": "content hash mismatch"}));
                continue;
            }
            verified += 1;
        }
    }
    // Registered packages must still resolve to immutable library content.
    let mut statement = db.prepare(
        "SELECT p.id,p.version,p.hash,l.hash,l.bundle,l.bundle_hash FROM craftmine_packages p
         LEFT JOIN craftmine_library l ON l.id=p.id AND l.version=p.version ORDER BY p.id,p.version",
    )?;
    let rows = statement
        .query_map([], |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, i64>(1)?,
                r.get::<_, String>(2)?,
                r.get::<_, Option<String>>(3)?,
                r.get::<_, Option<String>>(4)?,
                r.get::<_, Option<String>>(5)?,
            ))
        })?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    for (id, version, hash, library_hash, bundle, bundle_hash) in rows {
        let label = format!("package/{id}@{version}");
        match (library_hash, bundle, bundle_hash) {
            (Some(library_hash), Some(bundle), Some(bundle_hash)) => {
                if library_hash != hash || digest(&bundle) != bundle_hash {
                    mismatched.push(json!({"path": label, "reason": "library content mismatch"}));
                } else {
                    verified += 1;
                }
            }
            _ => missing.push(json!({"path": label, "reason": "library content missing"})),
        }
    }
    Ok(json!({"missing": missing, "mismatched": mismatched,
        "pathEscapes": path_escapes, "verified": verified}))
}

impl TaskJournal {
    pub fn backup_export_full(&mut self, args: &Value) -> Result<Value> {
        fields(args, &["operationId"])?;
        let id = text(args, "operationId", 240)?.to_owned();
        let request_hash = digest(&serde_json::to_string(args)?);
        let tx = self
            .db
            .transaction_with_behavior(TransactionBehavior::Immediate)?;
        let prior: Option<(String, String, String)> = tx
            .query_row(
                "SELECT request_hash,receipt,archive FROM craftmine_backup_jobs WHERE id=?1 AND kind='export-full'",
                [&id],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .optional()?;
        if let Some((old, receipt, archive)) = prior {
            ensure!(old == request_hash, "REPLAY_MISMATCH");
            let mut result: Value = serde_json::from_str(&receipt)?;
            result["archive"] = serde_json::from_str(&archive)?;
            return Ok(result);
        }
        let tables = super::snapshot(&tx)?;
        let domain = json!({"format": super::FORMAT_DOMAIN,
            "schemaVersion": super::SCHEMA_VERSION, "createdAt": worlds::timestamp()?,
            "tables": tables, "hash": digest(&serde_json::to_string(&tables)?)});
        let content = content_manifest(&tx)?;
        let mut archive = body(worlds::timestamp()?, &domain, &content);
        archive["hash"] = json!(digest(&serde_json::to_string(&archive)?));
        let serialized = serde_json::to_string(&archive)?;
        ensure!(serialized.len() <= super::LIMIT, "BACKUP_TOO_LARGE");
        super::job_capacity(&tx, serialized.len())?;
        let receipt = json!({"id": id, "kind": "export-full", "status": "completed",
            "manifest": {"hash": archive["hash"], "bytes": serialized.len(),
                "schemaVersion": SCHEMA_VERSION, "domainHash": domain["hash"],
                "contentFiles": content["legacyImports"].as_array().map(Vec::len).unwrap_or(0)},
            "rebuildableExcluded": archive["rebuildable"],
            "credentialsIncluded": false, "sessionIncluded": false});
        tx.execute(
            "INSERT INTO craftmine_backup_jobs(id,kind,status,request_hash,archive_hash,receipt,
             archive,created_at) VALUES(?1,'export-full','completed',?2,?3,?4,?5,?6)",
            params![
                id,
                request_hash,
                archive["hash"].as_str().context("BACKUP_HASH_REQUIRED")?,
                serde_json::to_string(&receipt)?,
                serialized,
                worlds::timestamp()?
            ],
        )?;
        tx.commit()?;
        let mut result = receipt;
        result["archive"] = archive;
        Ok(result)
    }

    /// Verifies both a complete archive and a plain domain archive. Any
    /// missing, mismatched or escaping entry makes the report invalid; nothing
    /// is repaired silently.
    pub fn backup_verify(&self, args: &Value) -> Result<Value> {
        fields(args, &["archive"])?;
        let archive = &args["archive"];
        if archive["format"] == super::FORMAT_DOMAIN {
            let report = super::validate_archive(&self.db, archive)?;
            return Ok(json!({"format": super::FORMAT_DOMAIN, "valid": true,
                "hash": report["hash"], "counts": report["counts"], "missing": [],
                "mismatched": [], "pathEscapes": [], "rebuildable": [], "verified": 0}));
        }
        fields(
            archive,
            &[
                "format",
                "schemaVersion",
                "createdAt",
                "domain",
                "content",
                "rebuildable",
                "provenance",
                "hash",
            ],
        )?;
        ensure!(archive["format"] == FORMAT, "BACKUP_VERSION_UNSUPPORTED");
        ensure!(
            archive["schemaVersion"].as_u64() == Some(SCHEMA_VERSION),
            "BACKUP_VERSION_UNSUPPORTED"
        );
        let mut claimed = archive.clone();
        claimed.as_object_mut().unwrap().remove("hash");
        ensure!(
            archive["hash"] == digest(&serde_json::to_string(&claimed)?),
            "BACKUP_HASH_MISMATCH"
        );
        let domain = super::validate_archive(&self.db, &archive["domain"])?;
        ensure!(
            domain["hash"] == archive["domain"]["hash"],
            "BACKUP_HASH_MISMATCH"
        );
        let content = content_report(&self.db, &self.directory, &archive["content"])?;
        let valid = content["missing"].as_array().unwrap().is_empty()
            && content["mismatched"].as_array().unwrap().is_empty()
            && content["pathEscapes"].as_array().unwrap().is_empty();
        Ok(json!({"format": FORMAT, "valid": valid, "hash": archive["hash"],
            "schemaVersion": SCHEMA_VERSION, "domainHash": domain["hash"],
            "counts": domain["counts"], "missing": content["missing"],
            "mismatched": content["mismatched"], "pathEscapes": content["pathEscapes"],
            "verified": content["verified"], "rebuildable": archive["rebuildable"],
            "credentialsIncluded": false}))
    }

    /// Content is verified before the atomic domain restore starts, so an
    /// incomplete backup cannot leave a half-restored profile.
    pub fn backup_restore_full(&mut self, args: &Value) -> Result<Value> {
        fields(args, &["operationId", "archive", "expectedCurrentHash"])?;
        let report = self.backup_verify(&json!({"archive": args["archive"]}))?;
        ensure!(
            report["valid"] == true,
            "BACKUP_CONTENT_INCOMPLETE: {} missing, {} mismatched, {} escaping",
            report["missing"].as_array().map(Vec::len).unwrap_or(0),
            report["mismatched"].as_array().map(Vec::len).unwrap_or(0),
            report["pathEscapes"].as_array().map(Vec::len).unwrap_or(0)
        );
        let receipt = self.backup_restore(&json!({
            "operationId": args["operationId"],
            "archive": args["archive"]["domain"],
            "expectedCurrentHash": args["expectedCurrentHash"]
        }))?;
        Ok(json!({"restore": receipt, "contentVerified": true,
            "verifiedFiles": report["verified"], "rebuildableExcluded": report["rebuildable"],
            "credentialsIncluded": false}))
    }

    /// Usage relations keep cleanup honest: a package still referenced by a
    /// live instance is reported instead of being archived away.
    pub fn backup_content_usage(&self, args: &Value) -> Result<Value> {
        fields(args, &[])?;
        let packages: i64 =
            self.db
                .query_row("SELECT COUNT(*) FROM craftmine_packages", [], |r| r.get(0))?;
        let instances: i64 = self
            .db
            .query_row("SELECT COUNT(*) FROM craftmine_package_instances", [], |r| {
                r.get(0)
            })?;
        let imports: i64 =
            self.db
                .query_row("SELECT COUNT(*) FROM craftmine_legacy_imports", [], |r| r.get(0))?;
        Ok(json!({"packages": packages, "instances": instances, "legacyImports": imports,
            "rebuildable": rebuildable()}))
    }
}
